insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('924ae3f2-1649-47f2-9291-17ffc83ea741', '09ae0adb-482e-46d3-ae65-24f984558a88', $$functie f(x) = x − x²$$,
   $$wiskunde-b-vwo-2021-i-parabool-en-twee-lijnen-context1.png$$,
   $$De functie f wordt gegeven door f(x) = x − x².$$, 'inline'),
  ('aed65036-91a8-4029-bc56-06ec9ac02d9d', '09ae0adb-482e-46d3-ae65-24f984558a88', $$top T, raaklijn l in O, loodlijn m door T en vlakdeel V$$,
   $$wiskunde-b-vwo-2021-i-parabool-en-twee-lijnen-context2.png$$,
   $$Het punt T(½, ¼) is de top van de grafiek van f.
De lijn l is de raaklijn aan de grafiek van f in de oorsprong.
De lijn m staat loodrecht op lijn l en gaat door T.
V is het vlakdeel dat wordt ingesloten door lijn m en de grafiek van f.
Zie de figuur.$$, 'inline'),
  ('857e0c79-61db-454f-9edf-fc09683ebc88', '09ae0adb-482e-46d3-ae65-24f984558a88', $$grafiek van f met de lijnen l en m en vlakdeel V (figuur)$$,
   $$wiskunde-b-vwo-2021-i-parabool-en-twee-lijnen-context3.png$$,
   $$figuur: grafiek van f met de raaklijn l, de lijn m en het grijze vlakdeel V$$, 'inline'),
  ('c70b84fe-0f8b-4535-9504-cd30d246d063', '7045e73c-4426-433e-b07b-4ac0108aad82', $$functies f(x) = 2sin(x) − sin(2x) en g(x) = sin(2x) op [0, 2π]$$,
   $$wiskunde-b-vwo-2021-i-goniometrische-functies-context1.png$$,
   $$De functies f en g worden voor 0 ≤ x ≤ 2π gegeven door:
f(x) = 2sin(x) − sin(2x)
g(x) = sin(2x)$$, 'inline'),
  ('72bbea81-76fe-4d4d-b723-c2a72592e044', '7045e73c-4426-433e-b07b-4ac0108aad82', $$vijf gemeenschappelijke punten, waaronder P en Q$$,
   $$wiskunde-b-vwo-2021-i-goniometrische-functies-context2.png$$,
   $$De grafieken van f en g hebben vijf gemeenschappelijke punten. Drie van deze punten liggen op de x-as. De andere twee punten zijn P en Q.
Zie figuur 1.$$, 'inline'),
  ('dae18afa-2ff4-4074-a3d4-952acb0e9edc', '7045e73c-4426-433e-b07b-4ac0108aad82', $$grafieken van f en g met P en Q (figuur 1)$$,
   $$wiskunde-b-vwo-2021-i-goniometrische-functies-context3.png$$,
   $$figuur 1: grafieken van f en g met de punten P en Q$$, 'inline'),
  ('217e8a0c-1f50-43e8-aab2-5c97af509af0', '7045e73c-4426-433e-b07b-4ac0108aad82', $$h is g 1 omhoog geschoven, ingesloten gebied V$$,
   $$wiskunde-b-vwo-2021-i-goniometrische-functies-context4.png$$,
   $$De grafiek van g wordt 1 omhoog geschoven. Zo ontstaat de grafiek van de functie h. Zie figuur 2.
V is het gebied dat wordt ingesloten door de grafieken van f en h. In figuur 2 is dit gebied grijs gemaakt.$$, 'inline'),
  ('3a558645-796d-4108-8aed-fb9779af758a', '7045e73c-4426-433e-b07b-4ac0108aad82', $$grafieken van f en h met gebied V (figuur 2)$$,
   $$wiskunde-b-vwo-2021-i-goniometrische-functies-context5.png$$,
   $$figuur 2: grafieken van f en h met het grijze gebied V$$, 'inline'),
  ('bf0c8a94-bad5-4615-bd63-c10469f119b3', '7045e73c-4426-433e-b07b-4ac0108aad82', $$snijpunten van f en h bij x ≈ 1,33 en x ≈ 2,97$$,
   $$wiskunde-b-vwo-2021-i-goniometrische-functies-context6.png$$,
   $$De grafieken van f en h snijden elkaar in twee punten. De x-coördinaten van deze twee punten zijn afgerond 1,33 en 2,97.$$, 'inline'),
  ('ff06fa6a-2238-4df2-90ba-d11c5154a128', '7045e73c-4426-433e-b07b-4ac0108aad82', $$functie k(x) = ½tan(x)$$,
   $$wiskunde-b-vwo-2021-i-goniometrische-functies-context7.png$$,
   $$De functie k wordt gegeven door k(x) = ½tan(x). Zie figuur 3, waarin de grafieken van k en f zijn weergegeven.$$, 'inline'),
  ('1f5b9370-ef7c-41e4-97e0-cf1510c993ce', '7045e73c-4426-433e-b07b-4ac0108aad82', $$grafieken van k en f (figuur 3)$$,
   $$wiskunde-b-vwo-2021-i-goniometrische-functies-context8.png$$,
   $$figuur 3: grafieken van k en f$$, 'inline'),
  ('255e0678-6dab-4764-b5b3-60a697285db8', '7045e73c-4426-433e-b07b-4ac0108aad82', $$k raakt f in het punt met x-coördinaat ⅓π$$,
   $$wiskunde-b-vwo-2021-i-goniometrische-functies-context9.png$$,
   $$De grafiek van k raakt de grafiek van f in een punt met x-coördinaat ⅓π.$$, 'inline'),
  ('fb6aea00-2c1a-40ee-91e8-e407f655857d', '4fa28bd9-75e0-4ff4-8a1c-bddc79587b01', $$epicentrum van een aardbeving$$,
   $$wiskunde-b-vwo-2021-i-aardbevingen-context1.png$$,
   $$Een aardbeving ontstaat op een plek in de aarde. Het punt recht boven die plek, op het aardoppervlak, heet het epicentrum van die aardbeving. We bekijken in deze opgave een model over aardbevingen, waarbij we ervan uitgaan dat de aardbeving in het epicentrum ontstaat.$$, 'inline'),
  ('52644d6f-4aec-47ca-8c25-541392594020', '4fa28bd9-75e0-4ff4-8a1c-bddc79587b01', $$snelheden primaire (6 km/s) en secundaire golf (3,5 km/s)$$,
   $$wiskunde-b-vwo-2021-i-aardbevingen-context2.png$$,
   $$Bij een aardbeving ontstaan verschillende typen golven in de aarde: primaire golven en secundaire golven. Primaire golven zijn sneller dan secundaire golven. We nemen in deze opgave aan dat een primaire golf een constante snelheid van 6 km/s heeft en een secundaire golf een constante snelheid van 3,5 km/s.$$, 'inline'),
  ('a7aba73c-52ab-4e47-a6c0-cf1b427838c4', '4fa28bd9-75e0-4ff4-8a1c-bddc79587b01', $$seismograaf: secundaire golf 17 seconden na de primaire golf, afstand d$$,
   $$wiskunde-b-vwo-2021-i-aardbevingen-context3.png$$,
   $$Een seismograaf is een meetinstrument waarmee je primaire en secundaire golven van elkaar kunt onderscheiden. Bij een bepaalde aardbeving registreert een seismograaf in een meetstation dat de eerste secundaire golf 17 seconden na de eerste primaire golf bij het meetstation aankomt. Met deze gegevens kun je de afstand d (in km ) van de seismograaf tot het epicentrum van de aardbeving bepalen.$$, 'inline'),
  ('59b9e7eb-cfe0-41ad-b6df-e18d36c647d5', '4fa28bd9-75e0-4ff4-8a1c-bddc79587b01', $$meetstations S(0, 0) en T(192, 128), afstanden 240 km en 80 km$$,
   $$wiskunde-b-vwo-2021-i-aardbevingen-context4.png$$,
   $$Om de plaats van het epicentrum te bepalen worden de meetgegevens van verschillende meetstations gecombineerd. In een bepaald gebied staan twee meetstations: S en T. Meetstation T ligt 192 km oostelijker en 128 km noordelijker dan meetstation S. Uit de metingen in meetstation S volgt dat het epicentrum van de aardbeving op een afstand van 240 km van dit meetstation S ligt. Uit de metingen in meetstation T volgt dat het epicentrum op 80 km van dit meetstation T ligt. Op grond van deze gegevens zijn er twee mogelijke plaatsen van het epicentrum aan te wijzen. Om deze plaatsen te bepalen worden de meetstations in een assenstelsel geplaatst, waarbij meetstation S in de oorsprong ligt. De coördinaten van meetstation T zijn dan (192, 128). Zie de figuur.$$, 'inline'),
  ('d9dfb5f6-73bc-4862-91e5-db21c891b364', '4fa28bd9-75e0-4ff4-8a1c-bddc79587b01', $$assenstelsel met de meetstations S en T (figuur)$$,
   $$wiskunde-b-vwo-2021-i-aardbevingen-context5.png$$,
   $$figuur: assenstelsel met meetstation S in de oorsprong en meetstation T$$, 'inline'),
  ('0ea0c73e-8a48-45b1-8ce5-075b4b7d952e', '4fa28bd9-75e0-4ff4-8a1c-bddc79587b01', $$magnitude van een aardbeving$$,
   $$wiskunde-b-vwo-2021-i-aardbevingen-context6.png$$,
   $$De zwaarte van een aardbeving wordt uitgedrukt in een getal: de magnitude. Een zware aardbeving heeft een grote magnitude, een lichte aardbeving heeft een kleine magnitude. De United States Geological Survey heeft voor verschillende magnitudes onderzocht hoe vaak aardbevingen met die magnitude in een bepaald gebied voorkwamen. Zie de tabel.$$, 'inline'),
  ('a38405b5-a7da-4e52-93da-8a71c9e01531', '4fa28bd9-75e0-4ff4-8a1c-bddc79587b01', $$tabel: gemiddeld aantal aardbevingen per jaar per magnitude$$,
   $$wiskunde-b-vwo-2021-i-aardbevingen-context7.png$$,
   $$tabel
magnitude | gemiddeld aantal aardbevingen per jaar
6,0 − 6,4 | 210
6,5 − 6,9 | 56
7,0 − 7,4 | 15
7,5 − 7,9 | 3,1
8,0 − 8,4 | 1,1
8,5 − 8,9 | 0,3$$, 'inline'),
  ('288230e3-b67c-4a34-94df-9044ca37c2d4', '4fa28bd9-75e0-4ff4-8a1c-bddc79587b01', $$model van Gutenberg en Richter N = 10^(a − bM)$$,
   $$wiskunde-b-vwo-2021-i-aardbevingen-context8.png$$,
   $$De onderzoekers Gutenberg en Richter hebben een model ontwikkeld om het aantal aardbevingen per jaar in een gebied te voorspellen. Dit model is van de vorm:
N = 10^(a − bM)
Hierin is M de magnitude en N het te verwachten aantal aardbevingen per jaar met deze magnitude M of groter. De waarden a en b zijn constanten.$$, 'inline'),
  ('5e009916-1a75-47c3-bba7-79a3c4f1edbf', '4fa28bd9-75e0-4ff4-8a1c-bddc79587b01', $$285,5 aardbevingen per jaar met M ≥ 6,0 en 4,5 met M ≥ 7,5$$,
   $$wiskunde-b-vwo-2021-i-aardbevingen-context9.png$$,
   $$Uit de tabel kun je afleiden dat er gemiddeld 285,5 aardbevingen per jaar zijn met een magnitude van 6,0 of groter. Ook kun je afleiden dat er gemiddeld 4,5 aardbevingen per jaar zijn met een magnitude van 7,5 of groter.$$, 'inline'),
  ('12fad07c-c42b-453a-86de-35c60f08719f', '4fa28bd9-75e0-4ff4-8a1c-bddc79587b01', $$voorspelling voor magnitude 6,5 of groter$$,
   $$wiskunde-b-vwo-2021-i-aardbevingen-context10.png$$,
   $$Met behulp van deze twee gegevens is het mogelijk de waarden van a en b uit te rekenen. Vervolgens kun je met dat model een voorspelling doen van het aantal aardbevingen per jaar met een magnitude van 6,5 of groter.$$, 'inline'),
  ('6ce168f0-dd01-4574-9689-383ce4a295f9', '5691bb0b-76bd-41bf-a2a0-698c5ee1b2a7', $$vierkant OABC, punten P(p, 0) en Q(1/p, 0) met 0 < p < 1$$,
   $$wiskunde-b-vwo-2021-i-een-vierkant-en-vier-vectoren-context1.png$$,
   $$Gegeven is het vierkant OABC met hoekpunten O(0,0), A(1,0), B(1,1) en C(0,1).
Verder zijn gegeven het punt P(p, 0) en het punt Q(1/p, 0), met 0 < p < 1.$$, 'inline'),
  ('e033ef58-c837-4520-ace1-833f5dcfb386', '5691bb0b-76bd-41bf-a2a0-698c5ee1b2a7', $$vectoren CP⃗, CA⃗ en CQ⃗$$,
   $$wiskunde-b-vwo-2021-i-een-vierkant-en-vier-vectoren-context2.png$$,
   $$In figuur 1 zijn de vectoren CP⃗, CA⃗ en CQ⃗ voor een willekeurige waarde van p weergegeven$$, 'inline'),
  ('7b46c766-83d5-4d64-9840-8073f495edb6', '5691bb0b-76bd-41bf-a2a0-698c5ee1b2a7', $$vierkant met de vectoren CP⃗, CA⃗ en CQ⃗ (figuur 1)$$,
   $$wiskunde-b-vwo-2021-i-een-vierkant-en-vier-vectoren-context3.png$$,
   $$figuur 1: vierkant OABC met de vectoren CP⃗, CA⃗ en CQ⃗$$, 'inline'),
  ('36687095-2335-43f2-9b18-33612c73a67f', '5691bb0b-76bd-41bf-a2a0-698c5ee1b2a7', $$M is het midden van PB, vector QM⃗$$,
   $$wiskunde-b-vwo-2021-i-een-vierkant-en-vier-vectoren-context4.png$$,
   $$M is het midden van lijnstuk PB. Zie figuur 2, waarin ook lijnstuk PB en vector QM⃗ zijn getekend.$$, 'inline'),
  ('f1ead9d4-d8ee-4c66-81dc-19214de5a498', '5691bb0b-76bd-41bf-a2a0-698c5ee1b2a7', $$vierkant met lijnstuk PB en vector QM⃗ (figuur 2)$$,
   $$wiskunde-b-vwo-2021-i-een-vierkant-en-vier-vectoren-context5.png$$,
   $$figuur 2: vierkant OABC met lijnstuk PB, midden M en vector QM⃗$$, 'inline'),
  ('d06f598a-44cc-4893-8352-5b6120442ee2', '5691bb0b-76bd-41bf-a2a0-698c5ee1b2a7', $$QM⃗ staat loodrecht op PB$$,
   $$wiskunde-b-vwo-2021-i-een-vierkant-en-vier-vectoren-context6.png$$,
   $$In figuur 2 is p zo gekozen dat vector QM⃗ loodrecht staat op lijnstuk PB.$$, 'inline'),
  ('28a8f032-8c2b-4e96-a8d6-fcb7caf698aa', '44c6a41c-d2c6-409c-a916-e4e1811ff584', $$bewegingsvergelijkingen x(t) = t², y(t) = t² − 2t$$,
   $$wiskunde-b-vwo-2021-i-limiet-van-een-verhouding-context1.png$$,
   $$De beweging van een punt P wordt beschreven door de volgende bewegingsvergelijkingen:
x(t) = t²
y(t) = t² − 2t$$, 'inline'),
  ('84f4540d-1a37-43f4-82d5-ceba4905dddb', '44c6a41c-d2c6-409c-a916-e4e1811ff584', $$lijn x = a snijdt de x-as in Q en de baan in R en S$$,
   $$wiskunde-b-vwo-2021-i-limiet-van-een-verhouding-context2.png$$,
   $$Gegeven is de lijn met vergelijking x = a, waarbij a > 0.
Deze lijn snijdt de x-as in punt Q en de baan van P in de punten R en S, waarbij de y-coördinaat van S groter is dan de y-coördinaat van R.
Zie de figuur.$$, 'inline'),
  ('2fd55913-2d2e-48d9-8b28-7ab8dd3fdfa7', '44c6a41c-d2c6-409c-a916-e4e1811ff584', $$baan van P met de lijn x = a (figuur)$$,
   $$wiskunde-b-vwo-2021-i-limiet-van-een-verhouding-context3.png$$,
   $$figuur: baan van P met de lijn x = a en de punten Q, R en S$$, 'inline'),
  ('1e9f07c4-88dd-40ba-a148-dec7b6fd149a', '44c6a41c-d2c6-409c-a916-e4e1811ff584', $$limiet van QR/QS als a onbegrensd toeneemt$$,
   $$wiskunde-b-vwo-2021-i-limiet-van-een-verhouding-context4.png$$,
   $$Als a onbegrensd toeneemt, nadert de verhouding QR/QS tot een limiet.$$, 'inline'),
  ('990c68a8-a73e-4696-b192-42f063922df9', 'c4af9505-da2b-426a-86d8-81c825452d46', $$functie fₚ(x) = (x³ + 4p)/x² voor p > 0$$,
   $$wiskunde-b-vwo-2021-i-gebroken-functie-met-een-parameter-context1.png$$,
   $$Voor p > 0 wordt de functie fₚ gegeven door:
fₚ(x) = (x³ + 4p)/x²$$, 'inline'),
  ('48aad269-971f-4bbd-9d2b-aff1de1bf78a', 'c4af9505-da2b-426a-86d8-81c825452d46', $$grafiek van f₁$$,
   $$wiskunde-b-vwo-2021-i-gebroken-functie-met-een-parameter-context2.png$$,
   $$In de figuur is de grafiek van f₁ weergegeven.$$, 'inline'),
  ('928ea9dd-1a99-4c49-877b-99996b4adc6d', 'c4af9505-da2b-426a-86d8-81c825452d46', $$grafiek van f₁ (figuur)$$,
   $$wiskunde-b-vwo-2021-i-gebroken-functie-met-een-parameter-context3.png$$,
   $$figuur: grafiek van f₁$$, 'inline'),
  ('63fd004b-f849-4115-8fe9-d84cef4bf355', 'c4af9505-da2b-426a-86d8-81c825452d46', $$f₁ heeft een scheve asymptoot$$,
   $$wiskunde-b-vwo-2021-i-gebroken-functie-met-een-parameter-context4.png$$,
   $$De grafiek van f₁ heeft een scheve asymptoot.$$, 'inline'),
  ('389f3c03-6cda-4ef9-9e72-35a958090b11', 'c4af9505-da2b-426a-86d8-81c825452d46', $$elke grafiek van fₚ heeft één top$$,
   $$wiskunde-b-vwo-2021-i-gebroken-functie-met-een-parameter-context5.png$$,
   $$Voor elke waarde van p > 0 heeft de grafiek van fₚ één top.$$, 'inline'),
  ('1b56f7cd-54cc-4bfc-b859-e5d91e0a4dfb', '3dd4e0b6-b83a-4be8-ae60-cebe1c4aa4ad', $$functie f(x) = |ln(x)| en de lijn y = q met punten A, B en C$$,
   $$wiskunde-b-vwo-2021-i-absolute-natuurlijke-logaritme-context1.png$$,
   $$De functie f wordt gegeven door f(x) = |ln(x)|.
Gegeven is verder de horizontale lijn met vergelijking y = q, met q > 0.
Deze lijn snijdt de y-as in het punt A en de grafiek van f in de punten B en C met x_B < x_C. Zie de figuur.$$, 'inline'),
  ('31520069-0ba1-4a2e-b8fa-331d904dd307', '3dd4e0b6-b83a-4be8-ae60-cebe1c4aa4ad', $$grafiek van f met de lijn y = q (figuur)$$,
   $$wiskunde-b-vwo-2021-i-absolute-natuurlijke-logaritme-context2.png$$,
   $$figuur: grafiek van f met de lijn y = q en de punten A, B en C$$, 'inline'),
  ('cd58d1d7-4af1-458d-91a5-30c169da1b4e', '3dd4e0b6-b83a-4be8-ae60-cebe1c4aa4ad', $$BC is drie keer zo lang als AB$$,
   $$wiskunde-b-vwo-2021-i-absolute-natuurlijke-logaritme-context3.png$$,
   $$Er is een waarde van q waarvoor de lengte van lijnstuk BC drie keer zo groot is als de lengte van lijnstuk AB.$$, 'inline'),
  ('d2a5e0b4-92fc-45fd-a43e-1182438615d5', 'b840ac49-00e4-4792-ad66-496165b65a64', $$functie f(x) = 6√x en punt P op de grafiek$$,
   $$wiskunde-b-vwo-2021-i-p-en-p-context1.png$$,
   $$De functie f wordt gegeven door f(x) = 6√x.
Het punt P is een punt op de grafiek van f rechts van de y-as.
Zie de figuur.$$, 'inline'),
  ('037893f9-139f-48ad-af24-bfc073c18630', 'b840ac49-00e4-4792-ad66-496165b65a64', $$grafiek van f met P, Pʹ en hoek van 120° (figuur)$$,
   $$wiskunde-b-vwo-2021-i-p-en-p-context2.png$$,
   $$figuur: grafiek van f met de punten P en Pʹ en de hoek van 120° bij O$$, 'inline'),
  ('93ab3481-1150-4ae0-a600-b5cd8d79fded', 'b840ac49-00e4-4792-ad66-496165b65a64', $$eigenschappen van Pʹ: op de negatieve x-as, OPʹ = OP, ∠POPʹ = 120°$$,
   $$wiskunde-b-vwo-2021-i-p-en-p-context3.png$$,
   $$In de figuur is het punt P zo gekozen dat er een punt Pʹ bestaat met de volgende eigenschappen:
– Pʹ ligt op de negatieve x-as;
– Lijnstuk OPʹ heeft dezelfde lengte als lijnstuk OP;
– ∠POPʹ = 120°.$$, 'inline');

